values (null, 'cars-2022', 'CARS Scrutineering Form', '{"format":1,"id":"cars-2022","bodyId":"cars","passtechRulesetIds":["cars-performance-rally","cars-rally-sprint"],"title":"CARS Scrutineering Form","revision":"D102_2022","source":{"form":"Canadian Association of Rallysport Scrutineering Form (D102_2022)","rules":"CARS Rule Book (National Rally Regulations and Technical Rules), 2026-03 (updated 2026-05-22)"},"instructions":"Overall result: Accepted or Rejected. This vehicle has been inspected for compliance only with CARS regulations. No guarantee regarding the safety of this vehicle is implied.","header":[{"id":"car_number","label":"Car / Voiture","type":"text","prefill":"car_number","required":true},{"id":"class","label":"Car class / Classe","type":"text","prefill":"class","required":true},{"id":"national_regional","label":"National / Regional","type":"choice","options":["National","Regional"]},{"id":"driver","label":"Driver / Pilote","type":"text","prefill":"driver","required":true},{"id":"logbook_number","label":"Logbook #","type":"text","prefill":"logbook_number"},{"id":"logbook_body","label":"Logbook issuer","type":"choice","options":["CARS/ASN","NASA","ARA","RA","Other FIA"],"prefill":"logbook_body"},{"id":"codriver","label":"Co-Driver / Co-pilote","type":"text","prefill":"codriver","required":true},{"id":"vin","label":"VIN #","type":"text","prefill":"vin"},{"id":"plate","label":"License Plate #","type":"text","prefill":"plate"}],"sections":[{"id":"lights","title":"Lights","items":[{"id":"auxiliary_lights","label":"Auxiliary lights","accepts":"Auxiliary lights fitted in bumper/grille/front bodywork with openings fully filled by the lights","rule":"CARS TR 12.4.3.2","allowNA":true},{"id":"single_switch_driving_lights","label":"Single switch driving lights","accepts":"One switch turns off all high beams and auxiliary lights, leaving low beams on","rule":"CARS TR 12.4.3.3","allowNA":true}]},{"id":"personal","title":"Driver / Co-Driver","items":[{"id":"helmet","label":"Helmet","perOccupant":true,"gear":"helmet","accepts":"FIA 8860-2010 (expires 2028-12-31), 8859-2015, 8860-2018 or 8859-2024; Snell SA2020 or SA2025. Snell SA2010/SAH2010/SA2015 on the form are no longer accepted for Performance Rally (Rally Sprint also accepts Snell SA2005 or newer). Unmodified","rule":"CARS NRR 11.1.6","options":["SNELL SA2010","SNELL SAH2010","SNELL SA2015","SNELL SA2020","FIA 8860-2010","FIA 8859-2015","FIA 8860-2018"]},{"id":"helmet_identification","label":"Helmet identification","perOccupant":true,"accepts":"Competitor''s name clearly marked on the helmet","rule":"CARS NRR 11.1.6"},{"id":"hnr","label":"Head & Neck restraint system","perOccupant":true,"gear":"hnr","accepts":"HANS FIA 8858-2002 or 8858-2010, Hybrid FIA 8858-2010, or SFI 38.1 with conformance label less than 5 years old","rule":"CARS NRR 11.1.7","options":["HANS 8858-2002","HANS 8858-2010","Hybrid 8858-2010"]},{"id":"hnr_tether","label":"Tether FIA 8858","perOccupant":true,"accepts":"FIA devices use FIA-homologated tethers with a sewn FIA 8858 label","rule":"CARS NRR 11.1.7"},{"id":"suit","label":"Driving suit","perOccupant":true,"gear":"firesuit","accepts":"FIA 8856-2000, 8856-2018 or FIA 1986; SFI 3-2A/5; SFI 3-2A/1 only with approved fire-resistant underwear; clean, neck to ankles and wrists, no holes or frays","rule":"CARS NRR 11.1.8","options":["FIA 8856-2000","FIA 1986","FIA 8856-2018","SFI 3-2A/5","SFI 3-2A/1"]},{"id":"undergarments","label":"Undergarments","perOccupant":true,"gear":"undergarment","accepts":"Approved fire-resistant underwear when the suit is SFI 3-2A/1","rule":"CARS NRR 11.1.8","allowNA":true},{"id":"belts","label":"Belts","perOccupant":true,"gear":"belts_harness","accepts":"Unmodified 5- or 6-point FIA 8853/98 or 8853-2016 (not past label expiration) or SFI 16.1/16.5 (manufacture date less than 2 years); no mixed parts. Rally Sprint: min. 5-point in good condition, no expiry restriction","rule":"CARS TR 12.3.3.1","options":["FIA 8853/98","FIA 8853-2016","SFI 16.1 (<2 yrs)","SFI 16.5 (<2 yrs)"],"fields":[{"id":"date","label":"Date","type":"date"}]},{"id":"belt_installation","label":"Belt installation","perOccupant":true,"accepts":"Lap and crotch straps through the seat, not over the sides; straps protected from sharp edges; anchorages per FIA/SFI guidance","rule":"CARS TR 12.3.3.3, 12.3.3.4"},{"id":"seat","label":"Seat","perOccupant":true,"gear":"seat","accepts":"FIA 8855-1999, 8862-2009 or 8855-2021, not modified; no hinged-back or OEM seats; replace at 10 years from manufacture (Rally Sprint: fixed-back one-piece FIA seat, no expiry)","rule":"CARS TR 12.3.12.1","options":["FIA 8855-1999","FIA 8862-2009"]},{"id":"seat_mounting","label":"Seat mounting elements","perOccupant":true,"accepts":"Mounted per FIA App. J Art. 253 Art. 16; no movement possible in an accident","rule":"CARS TR 12.3.12.2"},{"id":"seat_structure","label":"Seat structure to chassis","perOccupant":true,"accepts":"Seat securely attached to the floor/chassis; end plates bolted or fully welded","rule":"CARS TR 12.3.12.2"}]},{"id":"cage","title":"Cage","items":[{"id":"cage_padding","label":"Roll cage padding","accepts":"FIA 8857-2001 Type A or SFI 45.1 wherever a helmet could contact the cage; flame-retardant padding where bodies could contact it","rule":"CARS TR 12.3.2.6","options":["FIA 8857 2001, TYPE A","SFI 45.1"]}]},{"id":"motorisation","title":"Motorisation","items":[{"id":"turbo_restrictor","label":"Turbo & restrictor","accepts":"Forced induction inlet per class (Table A: O4WD 34 mm, 2.5 bar abs), min. 3 mm wide, within 50 mm of the compressor blades","rule":"CARS TR 12.4.10, 12.4.13","allowNA":true,"options":["N/A","34mm","32mm"]},{"id":"turbo_seal","label":"Turbo seal","accepts":"Induction system sealed with wire and CARS seal so the restrictor cannot be reached without breaking it","rule":"CARS TR 12.4.10","allowNA":true,"options":["Marked","Lead seal"],"fields":[{"id":"seal_number","label":"CARS No.","type":"text"}]},{"id":"exhaust","label":"Exhaust","accepts":"Functioning catalytic converter (unless registered before one was required); max. 86 dBA at 15 m with engine at 3500 rpm, stationary","rule":"CARS TR 12.4.5","options":["Catalyzer","dB @3500RPM / 15 meters"],"fields":[{"id":"sound_level","label":"Sound level","type":"number","unit":"dBA"}]},{"id":"fuel_tank_lines","label":"Fuel tank & lines","gear":"fuel_cell","accepts":"Original tank, or FIA/SFI fuel cell vented outside with original filler sealed; fire-retardant shield from cockpit; lines through cockpit metal-cased and 200 psi rated; pumps behind metal bulkhead; no supplementary tanks","rule":"CARS TR 12.3.11","options":["Original","Fuel cell","Fuel lines"]}]},{"id":"interior","title":"Vehicle Interior","items":[{"id":"door_panels","label":"Door panels","accepts":"Inside door panels protect from metal edges","rule":"CARS TR 12.3.15"},{"id":"secured_items","label":"Secured items","accepts":"All articles that could be dangerous if loose are securely restrained","rule":"CARS TR 12.3.14"},{"id":"spill_kit","label":"Spill kit","gear":"spill_kit","accepts":"At least 2 x 15\" x 19\" absorbent pads and 1 x 3\" x 48\" hydrocarbon sock in a resealable heavy-duty bag","rule":"CARS TR 12.3.25"},{"id":"first_aid_kit","label":"First Aid kit","gear":"first_aid_kit","accepts":"Comprehensive kit with the CARS-listed contents in the cockpit, easily accessible and removable","rule":"CARS TR 12.3.5"},{"id":"first_aid_sticker","label":"Sticker","accepts":"First-aid kit label on the outside of the car at the nearest access point","rule":"CARS TR 12.3.5"},{"id":"battery","label":"Battery","accepts":"Securely mounted, terminals covered; covered non-conductive box if relocated; sealed type if in the cockpit","rule":"CARS TR 12.3.7"},{"id":"triangles","label":"Triangles (3)","gear":"emergency_triangle","accepts":"3 self-supporting reflective triangles, min. 30 cm per side, one within reach of a seated crew member","rule":"CARS TR 12.3.6"},{"id":"triangle_identification","label":"Triangle identification","accepts":"Triangles identified/marked for the car"},{"id":"extinguisher_1","label":"Extinguisher (<2 yrs)","gear":"fire_extinguisher","accepts":"Two portable extinguishers min. 5 B:C each in the cockpit, min. two quick-release metal fastenings and anti-torpedo tabs, one within reach of a seated crew member; bought, recharged or inspected within 2 years; exterior extinguisher label. On-board (central) system optional: FIA 8865-2015 or SFI 17.1, min. 3 kg, in addition to the two portables","rule":"CARS TR 12.3.4","options":["Sticker","Portable","Central"],"fields":[{"id":"bc_rating","label":"Portable rating (BC)","type":"text"},{"id":"central_quantity","label":"Central quantity (kg or l)","type":"number"},{"id":"service_date","label":"Purchase / service date","type":"date"}]},{"id":"extinguisher_2","label":"Extinguisher (<2 yrs)","gear":"fire_extinguisher","accepts":"Second required portable extinguisher, min. 5 B:C, same mounting and 2-year service requirements","rule":"CARS TR 12.3.4","options":["Sticker","Portable","Central"],"fields":[{"id":"bc_rating","label":"Portable rating (BC)","type":"text"},{"id":"central_quantity","label":"Central quantity (kg or l)","type":"number"},{"id":"service_date","label":"Purchase / service date","type":"date"}]},{"id":"extinguisher_3","label":"Extinguisher (<2 yrs)","accepts":"Additional extinguisher or on-board system if fitted; same mounting and 2-year service requirements","rule":"CARS TR 12.3.4","allowNA":true,"options":["Sticker","Portable","Central"],"fields":[{"id":"bc_rating","label":"Portable rating (BC)","type":"text"},{"id":"central_quantity","label":"Central quantity (kg or l)","type":"number"},{"id":"service_date","label":"Purchase / service date","type":"date"}]}]},{"id":"bodywork","title":"Bodywork","items":[{"id":"drivers_names","label":"Drivers'' names","accepts":"Driver and co-driver names on the rear side windows, white 5 cm Helvetica bold","rule":"CARS TR 12.4.2.3, 12.4.2.4"},{"id":"flags","label":"Flags","accepts":"National or provincial flag, 5 cm high, next to each name","rule":"CARS TR 12.4.2.3"},{"id":"windows","label":"Windows","accepts":"Laminated safety-glass windshield; side glass may be replaced with Lexan of equal or greater thickness allowing escape and rescue","rule":"CARS TR 12.3.9","options":["Original","Polycarbonate"]},{"id":"window_tint","label":"Tint","accepts":"Crew visible from outside the car","allowNA":true,"fields":[{"id":"tint","label":"Tint","type":"number","unit":"%"}]},{"id":"sunroof","label":"Sunroof","accepts":"Metal sunroof fixed closed; non-metal sunroof replaced with metal and fixed closed","rule":"CARS TR 12.3.17","allowNA":true},{"id":"tires","label":"Tires","accepts":"Tires including spares adequate; studded tires only as permitted and marked at scrutineering","rule":"CARS TR 12.3.1, 12.4.4"},{"id":"suspension","label":"Suspension","accepts":"Suspension secure, no damage or excessive play"},{"id":"mud_flaps_ground_clearance","label":"Mud flaps & ground clearance","accepts":"Mud flaps on all rear and driving wheels; min. 5.0 cm ground clearance (excluding tires)","rule":"CARS TR 12.3.10, 12.3.19"},{"id":"tow_point_front","label":"Tow points: Front/identified","gear":"tow_hook","accepts":"Metal tow eye, min. 3/4\" inside diameter, painted yellow, red or orange, with \"TOW\" sticker","rule":"CARS TR 12.3.13"},{"id":"tow_point_rear","label":"Tow points: Rear/identified","gear":"tow_hook","accepts":"Metal tow eye, min. 3/4\" inside diameter, painted yellow, red or orange, with \"TOW\" sticker","rule":"CARS TR 12.3.13"},{"id":"tow_rope","label":"Tow rope","gear":"tow_rope","accepts":"Recovery strap carried entirely inside the car","rule":"CARS TR 12.3.16"}]}],"signoff":[{"id":"inspector","label":"Inspector","license":false}]}'::jsonb)
on conflict ((coalesce(body_id, '')), key) do update set title = excluded.title, definition = excluded.definition,
  version = tech_sheet_templates.version + 1, updated_at = now()
where tech_sheet_templates.definition is distinct from excluded.definition;

insert into tech_sheet_templates (body_id, key, title, definition)
values (null, 'nasa-rallysport', 'NASA Rally Sport Scrutineering Sheet', '{"format":1,"id":"nasa-rallysport","bodyId":"nasa","passtechRulesetIds":["nasa-rallysport"],"title":"NASA Rally Sport Scrutineering Sheet","revision":"2013","source":{"form":"NASA Rally Sport Scrutineering Sheet (2013 Sandblast Rally sample)","rules":"NASA Rally Sport GRR Section 3: Technical Regulations for Cars, v16.0"},"instructions":"Team declaration: I represent the car and team listed above and I certify the roadworthiness and road legality of the above listed vehicle. ''Roadworthiness'' includes, but is not limited to, the following items: FRONT END: headlights, driving lights, turn signals, parking lights, horn, windshield wipers and washers, rear view mirror. REAR END: tail lights, brake lights, license light, turn signals, backup lights. SUSPENSION AND RUNNING GEAR: steering linkage, suspension, shocks, wheel bearings, brakes, brake lines and hoses, wheels, tires, exhaust, service and parking brakes.","header":[{"id":"event","label":"Event","type":"text","prefill":"event","required":true},{"id":"type","label":"Type","type":"text"},{"id":"car_number","label":"Number","type":"text","prefill":"car_number","required":true},{"id":"driver","label":"Driver","type":"text","prefill":"driver","required":true},{"id":"codriver","label":"Navigator","type":"text","prefill":"codriver","required":true},{"id":"year","label":"Year","type":"number","prefill":"year"},{"id":"make","label":"Make","type":"text","prefill":"make"},{"id":"model","label":"Model","type":"text","prefill":"model"},{"id":"vin","label":"VIN","type":"text","prefill":"vin"},{"id":"plate","label":"Plate","type":"text","prefill":"plate"},{"id":"plate_state","label":"State","type":"text"},{"id":"driver_contact","label":"Driver contact","type":"text"},{"id":"codriver_contact","label":"Codriver contact","type":"text"},{"id":"team_representative","label":"Team Representative","type":"choice","options":["Driver","Codriver","Crew"]}],"sections":[{"id":"gear","title":"Driver Gear / Codriver Gear","items":[{"id":"helmet","label":"Helmet Expiration","perOccupant":true,"gear":"helmet","accepts":"Snell SA2015, SA2020 or newer; FIA 8860-2010, 8860-2018 or newer; FIA 8859-2015, 8859-2024 or newer; unmodified; not over 10 years old","rule":"NRS GRR 3.36.1.1","fields":[{"id":"helmet_date","label":"Helmet date","type":"date"}]},{"id":"hnr","label":"H&N Gear","perOccupant":true,"gear":"hnr","accepts":"SFI 38.1 (not expired), FIA 8858-2002 or 8858-2010 (FIA tethers not past manufacture year + 5)","rule":"NRS GRR 3.36.1.3"},{"id":"suit","label":"Suit Approved","perOccupant":true,"gear":"firesuit","accepts":"FIA 8856-2000, 8856-2018 or newer, or FIA 1986; SFI 3-2A/5; SFI 3-2A/1 only with FIA- or SFI-spec fire-resistant underwear","rule":"NRS GRR 3.36.1.2"},{"id":"required_patches","label":"Required Patches","perOccupant":true,"accepts":"Patches required by the series/event regulations sewn on the suit","allowNA":true}]},{"id":"exterior","title":"Exterior","items":[{"id":"windshield_windows","label":"Windshield/Windows","accepts":"Laminated safety-glass windshield free of structural damage; polycarbonate replacements min. 1/8\" allowing escape and rescue","rule":"NRS GRR 3.22"},{"id":"mud_flaps","label":"Mud Flaps (rear and drive wheels)","accepts":"Mud flaps on all wheels (current GRR; the form''s ''rear and drive wheels'' is older wording)","rule":"NRS GRR 3.32"},{"id":"tow_eyes","label":"Tow Eyes (front and rear)","gear":"tow_hook","accepts":"All-metal tow points front and rear on chassis/shell, golf-ball-size opening, painted/arrowed yellow, red or orange, reachable without crawling under the car","rule":"NRS GRR 3.26"},{"id":"damage_noted_logbook","label":"Safety related damage noted in log book","accepts":"Safety-related damage and repairs recorded in the log book"}]},{"id":"safety_equipment","title":"Safety Equipment","items":[{"id":"first_aid_kit","label":"First Aid Kit","gear":"first_aid_kit","accepts":"In the cockpit with antiseptic, gauze, adhesive tape, arm sling, safety pins, scissors, 2 space blankets and first aid manual","rule":"NRS GRR 3.16"},{"id":"fire_extinguishers","label":"Fire extinguisher 1x10BC or 2x5BC","gear":"fire_extinguisher","accepts":"Two or more hand-held extinguishers, min. 10 B:C each (or listed equivalents), in the cockpit, one within reach of a seated crew member; an on-board system does not count. The form''s 1x10BC or 2x5BC is superseded","rule":"NRS GRR 3.15.1, 3.15.2","fields":[{"id":"bc_rating","label":"BC rating(s)","type":"text"}]},{"id":"fire_extinguisher_date","label":"Fire extinguisher inspection date","accepts":"Purchased, inspected or recharged within the preceding 2 years (all extinguishers within reach)","rule":"NRS GRR 3.15.3","fields":[{"id":"inspection_date","label":"Inspection date","type":"date"}]},{"id":"triangles","label":"3 DOT Triangles (1 near codriver)","gear":"emergency_triangle","accepts":"3 self-supporting reflective triangles, min. 14 in tip to opposite side, one within reach of a seated crew member","rule":"NRS GRR 3.17"}]},{"id":"interior","title":"Interior","items":[{"id":"fuel_splash_shield","label":"FIA 2 volume fuel splash shield","accepts":"Two-volume (hatchback/wagon) cars: fuel-resistant, fire-retardant bulkhead fully separating tank, pump, filler and lines from the cockpit","rule":"NRS GRR 3.25.1","allowNA":true},{"id":"camera_mounts","label":"Camera Mounts","accepts":"Mounts cannot be struck by the crew; cameras over 0.5 lb secured at 2 points, non-elastic, non-plastic","rule":"NRS GRR 3.35","allowNA":true},{"id":"battery_interior","label":"Battery box, battery secure","accepts":"Metal-to-metal mounts; positive terminal covered unless in a non-conductive box; sealed type if in the cockpit","rule":"NRS GRR 3.19"},{"id":"harness","label":"Harness Expiration dates No exceptions","perOccupant":true,"gear":"belts_harness","accepts":"5-, 6- or 7-point harness of current FIA or SFI spec, no mixed parts; SFI not past tag date, FIA usable through Dec 31 of the label year. No exceptions","rule":"NRS GRR 3.10","fields":[{"id":"expires","label":"Expiration","type":"date"}]},{"id":"seat_secure","label":"Seats are secure","perOccupant":true,"accepts":"Firmly mounted to shell/chassis, fasteners min. 8 mm grade 5 / 8.8, no sliders","rule":"NRS GRR 3.9"},{"id":"seat_certified","label":"Seats are FIA cert or back brace","perOccupant":true,"gear":"seat","accepts":"FIA 8855-1999, 8855-2021 or 8862-2009 (later two with their supplied mount); the form''s ''back brace'' option is no longer accepted","rule":"NRS GRR 3.9"},{"id":"roll_cage","label":"Roll Cage","gear":"rollover_protection","accepts":"Cage and NRS (or FIA) log book required; FIA-homologated or built to FIA App. J Art. 253 with NRS tube sizes; older log books per their issue-year rules","rule":"NRS GRR 3.7"},{"id":"cage_padding","label":"Roll Cage padding","accepts":"FIA 8857-2001 Type A or SFI 45.1 wherever a helmet could contact the cage","rule":"NRS GRR 3.8.1"}]},{"id":"engine","title":"Engine Compartment","items":[{"id":"engine_fuel_oil_lines","label":"Fuel / Oil Lines / Pumps","accepts":"Lines and pumps secure, no leaks or chafing"},{"id":"engine_clean","label":"Clean and Neat","accepts":"Engine bay clean and neat"},{"id":"brake_fluid","label":"Brake Fluid Level","accepts":"Reservoir at proper level, no leaks"},{"id":"battery_engine","label":"Battery box, battery secure","accepts":"Metal-to-metal mounts; positive terminal covered unless in a non-conductive box","rule":"NRS GRR 3.19"},{"id":"wiring","label":"Wiring","accepts":"Wiring secure; battery primary wiring not routed between cage tubing and shell","rule":"NRS GRR 3.19.2"},{"id":"fluid_leaks","label":"Fluid Leaks","accepts":"No fluid leaks"}]},{"id":"trunk","title":"Trunk","items":[{"id":"fuel_tank","label":"Fuel Tank / Fuel Cell","gear":"fuel_cell","accepts":"OEM tank in OEM location with OEM mounts, or SFI 28.3 / FIA FT3, FT3.5 or FT5 bladder cell in a metal container, vented outside, not more than 5 years from manufacture (or manufacturer recertified)","rule":"NRS GRR 3.25, 3.25.2"},{"id":"fuel_bulkhead","label":"Bulkhead","accepts":"Fuel-resistant, fire-retardant solid bulkhead fully separating tank, pump, filler, connections and vents from the cockpit; access panels sealed","rule":"NRS GRR 3.25.1"},{"id":"trunk_fuel_lines_pumps","label":"Fuel Lines and Pumps","accepts":"Lines through cockpit metal-cased, 200 psi, no cockpit connectors; pumps run only with engine running and behind a sealed metal bulkhead","rule":"NRS GRR 3.25.4-3.25.6"},{"id":"battery_trunk","label":"Battery box, battery secure","accepts":"Metal-to-metal mounts; relocated flooded batteries in a covered non-conductive box","rule":"NRS GRR 3.19"},{"id":"tow_rope","label":"Tow Rope","gear":"tow_rope","accepts":"Kinetic recovery rope/strap, min. 3/4\" thick and 19 ft long, no metal ends, stowed inside the car","rule":"NRS GRR 3.27"},{"id":"spares_secure","label":"Spares secure","accepts":"Spare wheel and spares firmly secured; no loose articles","rule":"NRS GRR 3.13, 3.28"}]},{"id":"turbo_restrictor","title":"Turbo Restrictor","items":[{"id":"restrictor_size","label":"Size in mm","accepts":"Open AWD Heavy: max. 34 mm internal (twin compressors 22.6 mm each); not required in other classes","rule":"NRS GRR 3.14.1","allowNA":true,"fields":[{"id":"size","label":"Restrictor size","type":"number","unit":"mm"}]},{"id":"restrictor_sealed","label":"Sealed? Y/N","accepts":"Fasteners drilled and wired/sealed so the restrictor cannot be removed without removing the wire","rule":"NRS GRR 3.14.2","allowNA":true,"fields":[{"id":"seal_number","label":"Seal number","type":"text"}]},{"id":"restrictor_external","label":"External Y/N","accepts":"Restrictor fixed to the compressor housing inlet, single piece, min. 3 mm long, all intake air through it","rule":"NRS GRR 3.14.2","allowNA":true}]},{"id":"measurements","title":"Measurements","items":[{"id":"exhaust_noise","label":"Exhaust noise level DBA","accepts":"Max. 105 dBA at 2500 rpm, 18 in from the outlet, 45 degrees off centerline","rule":"NRS GRR 3.24","fields":[{"id":"level","label":"Sound level","type":"number","unit":"dBA"}]},{"id":"catalytic_converter","label":"Catalytic Converter (stock class only)","accepts":"Functioning catalytic converter where the class requires it","allowNA":true},{"id":"tread_depth","label":"Tread depth (tarmac rally only)","accepts":"Tarmac events: 5.5 mm molded tread pattern, min. 1.6 mm over three quarters of the tread; no slicks or DOT-R tires","rule":"NRS GRR 3.13.1","allowNA":true,"fields":[{"id":"depth","label":"Tread depth","type":"number","unit":"mm"}]},{"id":"weight","label":"Weight","accepts":"At or above the class minimum weight (no fuel, crew or crew equipment)","rule":"NRS GRR 3.2.4","allowNA":true,"fields":[{"id":"weight","label":"Weight","type":"number","unit":"lb"}]}]},{"id":"stickers","title":"Stickers","items":[{"id":"race_number","label":"Race Number Correct","accepts":"Assigned race number displayed correctly"},{"id":"number_header_footer","label":"Correct Number header and footer","accepts":"Correct number header and footer decals"},{"id":"event_sponsors","label":"Event Sponsors","accepts":"Event sponsor decals placed as instructed"},{"id":"other_body_stickers_covered","label":"RA / CARS stickers completely covered / removed","accepts":"Other sanctioning bodies'' stickers fully covered or removed"},{"id":"contingency_stickers","label":"List any contingency stickers","accepts":"Contingency stickers recorded","allowNA":true,"fields":[{"id":"list","label":"Contingency stickers","type":"text"}]}]},{"id":"logbook","title":"Log Book","items":[{"id":"logbook_body","label":"Log Book Sanctioning Body","accepts":"NRS log book, or another body''s log book accepted for inspection","rule":"NRS GRR 3.7","fields":[{"id":"body","label":"Sanctioning body","type":"text","prefill":"logbook_body"}]},{"id":"logbook_number","label":"Log Book Number","accepts":"Log book number recorded","fields":[{"id":"number","label":"Log book number","type":"text","prefill":"logbook_number"}]},{"id":"logbook_address","label":"Address on last page of log book?","accepts":"Current owner contact information recorded in the log book","rule":"NRS GRR 3.7.6"},{"id":"logbook_event_page","label":"Page for this event filled out by entrant?","accepts":"Event page completed by the entrant"},{"id":"homologation_papers","label":"Correct homologation papers (Group A/N only)","accepts":"Current FIA homologation papers for the car","allowNA":true},{"id":"vin_matches","label":"VIN above matches logbook and car","accepts":"VIN on this sheet matches the log book and the car''s shell","rule":"NRS GRR 3.7.6"}]}],"signoff":[{"id":"team","label":"Team representative","license":false},{"id":"scrutineer","label":"Scrutineer","license":false}]}'::jsonb)
on conflict ((coalesce(body_id, '')), key) do update set title = excluded.title, definition = excluded.definition,
  version = tech_sheet_templates.version + 1, updated_at = now()
where tech_sheet_templates.definition is distinct from excluded.definition;

insert into tech_sheet_templates (body_id, key, title, definition)
values (null, 'neha', 'NEHA Tech Inspection Form', '{"format":1,"id":"neha","bodyId":"neha","passtechRulesetIds":["neha-competitive","neha-x"],"title":"NEHA Tech Inspection Form","revision":"undated","source":{"form":"NEHA Tech Inspection Form (page 1, standard) and NEHA Tech Inspection Form X Car (page 2)","rules":"New England Hillclimb Association Rules, 2026 Edition"},"variants":[{"id":"standard","label":"Standard"},{"id":"x","label":"X car"}],"header":[{"id":"car_number","label":"Car number","type":"text","prefill":"car_number","required":true},{"id":"class","label":"Class","type":"text","prefill":"class","required":true},{"id":"driver","label":"Driver","type":"text","prefill":"driver","required":true},{"id":"logbook","label":"Logbook","type":"choice","options":["NEHA","ARA","NASA","CARS","OTHER"],"prefill":"logbook_body"},{"id":"logbook_other","label":"Logbook (other)","type":"text"}],"sections":[{"id":"helmet","title":"Helmet","items":[{"id":"helmet","label":"Helmet","gear":"helmet","accepts":"Snell SA2015 or newer (SA2015 discontinued after the 2026 season); FIA 8860-2010, 8859-2015, 8860-2018 or 8859-2024 less than 10 years from manufacture; good condition","rule":"NEHA 1.3.3","options":["SA2015 or newer","FIA 8860-2010, 8859-2015, 8860-2018, 8859-2024 (<10 years from manufacture)"]}]},{"id":"hans","title":"HANS","items":[{"id":"hnr","label":"HANS","gear":"hnr","accepts":"HANS FIA 8858-2002 or 8858-2010, Hybrid FIA 8858-2010, or SFI 38.1 with conformance label less than 5 years old","rule":"NEHA 1.4.2","variants":["standard"],"options":["FIA 8858-2002","FIA 8858-2010","Hybrid 8858-2010","SFI 38.1 (cert date <5 years)"]},{"id":"hnr_tether","label":"Tether no older than 5 years","accepts":"Tethers less than 5 years old","rule":"NEHA 1.4.2.4","variants":["standard"],"fields":[{"id":"tether_date","label":"Tether date","type":"date"}]}]},{"id":"suit","title":"Suit / Clothes","items":[{"id":"firesuit","label":"Suit","gear":"firesuit","accepts":"FIA 8856-2000 or 8856-2018; SFI 3.2A/5 or 3.4/5; FIA 1986 or SFI 3.2A/1 only with FIA 8856-2000 or SFI 3.3 underwear; nothing worn over the suit","rule":"NEHA 1.4.1.2, 1.4.1.3","variants":["standard"],"options":["FIA 8856-2000","FIA 8856-2018","FIA 1986 Standard","SFI 3.2A/5","SFI 3.4/5","SFI 3.2A/1 with FIA 8856-2000 or SFI 3.3 undergarments"]},{"id":"suit_condition","label":"No rips, tears, oil stains","accepts":"Suit covers neck to ankles and wrists; clean, no defects, stains, holes or frays","rule":"NEHA 1.4.1.4","variants":["standard"]},{"id":"long_clothing","label":"Long pants / long shirt (X car)","accepts":"Full clothing (long sleeves, long pants, socks) of fire-resistant material such as cotton, linen, leather or wool; no meltable synthetics","rule":"NEHA 1.3.1","allowNA":true,"variants":["x"]},{"id":"firesuit_x","label":"Fire suit","gear":"firesuit","accepts":"Fire suit in good condition, worn instead of fire-resistant long pants/long shirt (a certified suit is not required for X cars)","variants":["x"],"allowNA":true},{"id":"gloves","label":"FIA or SFI gloves","gear":"gloves","accepts":"SFI or FIA rated gloves, no stains or holes","rule":"NEHA 1.4.1.5","variants":["standard"]}]},{"id":"belts","title":"Belts","items":[{"id":"belts","label":"Belts","gear":"belts_harness","accepts":"5-, 6- or 7-point SFI 16.1/16.5 or FIA 8853/2016 or 8853/98 harness; not past tagged expiration or more than 5 years from manufacture (untagged = out of date); no Y or V shoulder harness","rule":"NEHA 1.4.3.1, 1.4.3.2, 1.4.3.5","variants":["standard"],"options":["FIA 8853/2016","FIA 8853/98","SFI 16.5","SFI 16.1"],"fields":[{"id":"expires","label":"Year / month of expiration","type":"date"}]},{"id":"belts_not_mismatched","label":"Belts not mismatched","accepts":"Complete harness set, parts not mixed between sets; not altered from original condition","rule":"NEHA 1.4.3.4","variants":["standard"]},{"id":"belt_angles","label":"Belt angles","accepts":"Belt angles per SFI installation guide, FIA App. J Art. 253 section 6.2, or harness manufacturer","rule":"NEHA 1.4.3.6","variants":["standard"]},{"id":"belt_anchoring","label":"Belt anchoring points","accepts":"Anchor points per installation guide, each capable of 3300 lbf (OE anchor points adequate); correct hardware","rule":"NEHA 1.4.3.3, 1.4.3.6, 1.4.3.7","variants":["standard"]},{"id":"belt_clip_pins","label":"Pins in clips if used","accepts":"Safety pins fitted in snap-hook clips where clips are used","variants":["standard"],"allowNA":true},{"id":"belts_triple_wrapped","label":"Triple wrapped belts","accepts":"Wrap-around mounts and adjusters threaded/locked per harness manufacturer","variants":["standard"],"allowNA":true},{"id":"belts_no_fraying","label":"No fraying","gear":"belts_harness","accepts":"Belts in good condition, no fraying; OE 3-point belts are adequate for X cars","rule":"NEHA 1.3.11.2","variants":["x"]}]},{"id":"seats","title":"Seat(s)","items":[{"id":"seat_mounting","label":"Proper mounting","gear":"seat","accepts":"Seat mounted to substantial structure in line with harness loads (OE mountings adequate); with a 5+ point harness, fixed-back racing seat","rule":"NEHA 1.3.11, 1.4.4.2, 1.4.4.4"},{"id":"seat_no_play","label":"No play","accepts":"No play in the seat","rule":"NEHA 1.4.4.3"},{"id":"seat_no_alteration","label":"No alteration","accepts":"Seat not altered; safe condition","rule":"NEHA 1.3.11.1, 1.4.4.1"},{"id":"seat_fitment","label":"Seat fitment for all drivers (if shared car)","accepts":"Seat width and height fit each driver; headrest max. 3 in behind the helmet","rule":"NEHA 1.4.4.2","variants":["standard"],"allowNA":true}]},{"id":"interior","title":"Car interior / Cage","items":[{"id":"cage_padding","label":"Cage padding where head could hit bars","accepts":"High-density shock-absorbing padding (SFI or FIA) on any cage member the driver''s head can reach","rule":"NEHA 1.4.6.2","variants":["standard"],"options":["SFI","FIA"]},{"id":"fire_extinguisher","label":"2.5lb ABC fire extinguisher","gear":"fire_extinguisher","accepts":"Min. 2.5 lb ABC portable extinguisher with gauge, within reach of the driver, not on the driver''s footwell floor","rule":"NEHA 1.3.9.1, 1.3.9.4, 1.3.9.5"},{"id":"extinguisher_tag","label":"Extinguisher tag within 3 years","accepts":"Inspection tag or manufacture date within the last 3 years","rule":"NEHA 1.3.9.2","fields":[{"id":"tag_date","label":"Tag / manufacture date","type":"date"}]},{"id":"extinguisher_anti_torpedo","label":"Extinguisher anti-torpedo bracket","accepts":"Bracket securely mounted with anti-torpedo tab","rule":"NEHA 1.3.9.3"},{"id":"extinguisher_metal_bracket","label":"Extinguisher metal bracket / strap","accepts":"Metal bracket and latching metal strap; over 2.5 lb net needs an extra metal restraint","rule":"NEHA 1.3.9.4, 1.3.9.6"},{"id":"extinguisher_gauge","label":"Extinguisher gauge in green","accepts":"Gauge reads in the green","rule":"NEHA 1.3.9.1"},{"id":"air_horn","label":"Air horn","accepts":"Compressed air horn secured within reach of the driver","rule":"NEHA 1.3.18"},{"id":"battery_positive_interior","label":"Battery positive covered","accepts":"Positive terminal covered with a non-conducting cover","rule":"NEHA 1.3.13.3"},{"id":"battery_sealed","label":"Battery sealed from driver","accepts":"Battery securely mounted and sealed from the driver; insulated box if sharing a compartment with the fuel tank","rule":"NEHA 1.3.13.2, 1.3.13.4"},{"id":"spill_kit","label":"Spill kit","gear":"spill_kit","accepts":"Disposal (trash) bag carried for fluid-spill debris","rule":"NEHA 1.3.10.3"},{"id":"fuel_cell_bulkhead","label":"Fuel cell bulkhead","gear":"fuel_cell","accepts":"Gas tank or fuel cell sealed from the driver (SFI/FIA fuel cells count as sealed); secure, no leaks","rule":"NEHA 1.3.14.1-1.3.14.3","variants":["standard"]},{"id":"kill_switch","label":"Kill switch in Prepared and FL cars","gear":"kill_switch","accepts":"Prepared and FL classes: switch isolates all electrical power, marked with lightning bolt symbol and OFF position","rule":"NEHA 1.4.7","variants":["standard"],"allowNA":true},{"id":"fuel_lines_inside_cage","label":"Fuel lines run inside the cage","accepts":"Fuel lines securely mounted and protected from heat, collision and abrasion","rule":"NEHA 1.3.14.6","variants":["standard"]},{"id":"wires_inside_cage","label":"Wires run inside the cage","accepts":"No frayed, loose or pinchable wires; battery cable not through frame rails or cage tubing","rule":"NEHA 1.3.13.1","variants":["standard"]},{"id":"no_loose_objects","label":"No loose objects, no floor mats","accepts":"No loose objects, carpets or mats; small items in a closed compartment or secured","rule":"NEHA 1.3.10.1, 1.3.10.2"},{"id":"spare_tire","label":"Spare tire removed or properly secured","accepts":"Spare removed or securely restrained"}]},{"id":"under_hood","title":"Under Hood","items":[{"id":"oil_leaks","label":"No excessive oil leaks","accepts":"No oil leaks; no excessive oil in the engine compartment","rule":"NEHA 1.3.16.1, 1.3.16.2"},{"id":"oil_catch_can","label":"Oil catch can","accepts":"Oil overflow catch can or breather system, or OEM system in place","rule":"NEHA 1.3.16.3","variants":["standard"]},{"id":"oil_catch_can_x","label":"Oil catch can or OEM PCV","accepts":"Oil overflow catch can or breather system, or OEM system in place","rule":"NEHA 1.3.16.3","variants":["x"]},{"id":"firewall","label":"Firewall between engine and driver","accepts":"Firewall between engine and driver","rule":"NEHA 1.3.8.3"},{"id":"brake_fluid","label":"Brake fluid full","accepts":"Master cylinder full, no leaks","rule":"NEHA 1.3.6.1, 1.3.6.2"},{"id":"battery_positive_hood","label":"Battery positive covered","accepts":"Positive terminal covered with a non-conducting cover","rule":"NEHA 1.3.13.3"}]},{"id":"exterior","title":"Exterior / Wheels / Suspension","items":[{"id":"numbers","label":"Numbers","accepts":"Legible numbers on both sides with class designation, max. 3 numerals, no leading zeros; other drivers'' numbers covered","rule":"NEHA 1.3.19.1, 1.3.19.3"},{"id":"x_marking_if_required","label":"X if required","accepts":"\"X\" after the number on breakout vehicles","rule":"NEHA 1.3.19.2","variants":["standard"],"allowNA":true},{"id":"x_marking","label":"X","accepts":"\"X\" after the number","rule":"NEHA 1.3.19.2","variants":["x"]},{"id":"r_marking","label":"R if required","accepts":"\"R\" after the number on Rally vehicles","rule":"NEHA 1.3.19.2","variants":["standard"],"allowNA":true},{"id":"windshield","label":"DOT windshield or lexan or helmet with visor","accepts":"DOT windshield or polycarbonate (Lexan) windshield, or full-face helmet with visor; no acrylic/Plexiglas","rule":"NEHA 1.3.4.1"},{"id":"wheel_bearings_ball_joints","label":"Minimal play in wheel bearings and ball joints","accepts":"Ball joints, bushings and rod ends within manufacturer spec; wheel bearings minimal play and secure","rule":"NEHA 1.3.5.1, 1.3.5.2"},{"id":"lug_nuts","label":"No missing or loose lug nuts","accepts":"No missing or loose lugs; no cracked, broken or badly bent wheels","rule":"NEHA 1.3.7.1, 1.3.7.2"},{"id":"tires","label":"Tires in good condition","accepts":"Street tires: visible tread full width, no cord separation, DOT number, good condition","rule":"NEHA 1.3.7.3"}]}],"signoff":[{"id":"scrutineer","label":"Tech Inspector","license":false}]}'::jsonb)
on conflict ((coalesce(body_id, '')), key) do update set title = excluded.title, definition = excluded.definition,
  version = tech_sheet_templates.version + 1, updated_at = now()
where tech_sheet_templates.definition is distinct from excluded.definition;

insert into tech_sheet_templates (body_id, key, title, definition)
values (null, 'sccnh-gravel-trials', 'SCCNH Gravel Trial Tech Form', '{"format":1,"id":"sccnh-gravel-trials","bodyId":"sccnh","passtechRulesetIds":["sccnh-gravel-trials"],"title":"SCCNH Gravel Trial Tech Form","revision":"undated","source":{"form":"SCCNH Gravel Trial Tech Form","rules":"2026 SCCNH Gravel Trials Rules, Rev 1 12/2025"},"instructions":"Teams will inspect items marked \"team\". Scrutineer will check safety related items.","header":[{"id":"event","label":"Event","type":"text","prefill":"event","required":true},{"id":"car_number","label":"Car #","type":"text","prefill":"car_number","required":true},{"id":"class","label":"Class","type":"choice","options":["R2U","R2O","R4U","R4O","EX"],"prefill":"class","required":true},{"id":"driver","label":"Driver","type":"text","prefill":"driver","required":true},{"id":"make_model","label":"Make/Model","type":"text"},{"id":"codriver","label":"Co-driver","type":"text","prefill":"codriver","required":true},{"id":"vin","label":"Vin #","type":"text","prefill":"vin"}],"sections":[{"id":"personal","title":"Personal Safety Equipment","items":[{"id":"helmet","label":"Helmet","perOccupant":true,"gear":"helmet","accepts":"Snell SA2015 (expires end of 2026), EA2016, SA2020 or SA2025; FIA 8860-2010, 8859-2015, 8860-2018 or 8859-2024 less than 10 years from manufacture; dual FIA/Snell: later expiration applies","rule":"SCCNH GT 12.1"},{"id":"suit","label":"Suit","perOccupant":true,"gear":"firesuit","accepts":"FIA 8856-2000, 8856-2018 or FIA 1986; SFI 3-2A/5 or 3-4A/5; SFI 3-2A/1 only with approved fire-resistant underwear","rule":"SCCNH GT 12.3"},{"id":"hnr","label":"Head and Neck Device","perOccupant":true,"gear":"hnr","accepts":"FIA 8858-2002 or 8858-2010, or SFI 38.1 with conformance label less than 5 years old; mounted per manufacturer","rule":"SCCNH GT 12.2"}]},{"id":"logbook","title":"Logbook","items":[{"id":"logbook","label":"Organization and #","accepts":"Log book from Rally America, SCCA Pro Rally, CARS, ARA, FIA or NASA Rallysport (other organizations need Chairman approval)","rule":"SCCNH GT 8","fields":[{"id":"organization","label":"Organization","type":"text","prefill":"logbook_body"},{"id":"number","label":"Logbook #","type":"text","prefill":"logbook_number"}]},{"id":"logbook_deficiency_repaired","label":"Logbook deficiency repaired","accepts":"Deficiencies noted in the log book have been repaired","allowNA":true}]},{"id":"front_end","title":"Vehicle Front End","items":[{"id":"auxiliary_lights","label":"Auxiliary Lights","accepts":"Securely mounted, no higher than the top of the hood, beam toward the front","rule":"SCCNH GT 13.4","allowNA":true},{"id":"headlights","label":"Headlights high/low beams","accepts":"Headlights function properly, high and low beam","rule":"SCCNH GT 13.4"},{"id":"directionals_front","label":"Directionals","accepts":"Front turn signals work"},{"id":"wiper_washer","label":"Windshield wiper and washer","checkedBy":"team","accepts":"Wipers and washer work"},{"id":"horn","label":"Horn","checkedBy":"team","accepts":"Works"},{"id":"hood_pins","label":"Hood pins","gear":"hood_pins","accepts":"Hood fixed closed with hood pins accessible from outside; other fasteners inoperative except secondary catch","rule":"SCCNH GT 9.9"},{"id":"towing_eye_front","label":"Towing eye","gear":"tow_hook","accepts":"Front tow point present and sound","rule":"SCCNH GT 9.7"}]},{"id":"rear_end","title":"Vehicle Rear End","items":[{"id":"tail_lights","label":"Tail lights","accepts":"Taillights function properly","rule":"SCCNH GT 13.4"},{"id":"brake_lights","label":"Brake lights","accepts":"Brake lights work"},{"id":"directionals_rear","label":"Directionals","accepts":"Rear turn signals work"},{"id":"reverse_lights","label":"Reverse lights","checkedBy":"team","accepts":"Work"},{"id":"license_plate_lights","label":"License plate lights","checkedBy":"team","accepts":"Work"},{"id":"tow_eye_rear","label":"Tow eye","gear":"tow_hook","accepts":"Rear tow point present and sound","rule":"SCCNH GT 9.7"}]},{"id":"exterior","title":"Exterior of Vehicle","items":[{"id":"neat_clean","label":"Neat and clean","checkedBy":"team","accepts":"Car presented neat and clean"},{"id":"windshield","label":"Windshield - safety glass","accepts":"Laminated safety-glass windshield, no damage obstructing vision"},{"id":"windows_in_place","label":"Windows in place","checkedBy":"team","accepts":"All windows in place"},{"id":"rear_view_mirror","label":"Rear view mirror","checkedBy":"team","accepts":"Present and secure"},{"id":"crew_names","label":"Driver/Co-driver names","accepts":"Driver and co-driver names displayed on the car","allowNA":true},{"id":"event_sponsor","label":"Event sponsor","accepts":"Event decals placed as instructed at tech","rule":"SCCNH GT 28"},{"id":"numbers_class","label":"Numbers and class","accepts":"Car numbers min. 8 in tall, 1.25 in brush width, supplied by the entrant (class marking N/R)","rule":"SCCNH GT 14.2","allowNA":true},{"id":"mud_flaps","label":"Mud flaps-rear and driven wheels","accepts":"Mud flaps behind rear and driven wheels"},{"id":"other_org_decals","label":"Other Org decals cover''d/remov''d","accepts":"Rally school decals other than Team O''Neil (e.g. The Firm, DirtFish) and any SCCA decals removed or covered","rule":"SCCNH GT 28"}]},{"id":"interior","title":"Vehicle Interior Compartments","items":[{"id":"roll_cage","label":"Roll cage legality","gear":"rollover_protection","accepts":"Six-point mounting, A-pillar supports, min. two door bars per side, diagonals to each top corner of the main hoop, min. tubing 1.5\" x 0.095\" (regardless of log book)","rule":"SCCNH GT 9.1"},{"id":"cage_padding","label":"FIA or SFI roll cage padding","accepts":"SFI 45.1 or FIA 8857-2001 Type A on any bar the helmet can reach, including roofline bars and bars forward of the main hoop","rule":"SCCNH GT 9.2"},{"id":"floor_firewall","label":"Floor pan and firewall, no holes","accepts":"No holes in floor pan or firewall"},{"id":"door_structure","label":"Door structure or impact panel","accepts":"Door structure intact or impact panel fitted; no exposed sharp edges"},{"id":"restraints","label":"Restraints , SFI/ FIA-5 yrs","gear":"belts_harness","accepts":"5-, 6- or 7-point harness for driver and co-driver, FIA 8853/98 or 8853/2016 or SFI 16.1/16.5, single-latch release; not past expiration and not older than 5 years from manufacture","rule":"SCCNH GT 9.4","fields":[{"id":"driver_expires","label":"Driver harness expiration","type":"date"},{"id":"codriver_expires","label":"Co-driver harness expiration","type":"date"}]},{"id":"restraint_mounting","label":"Restraints angles/anchors/pins","accepts":"Harness angles, anchors and hardware installed per manufacturer''s instructions","rule":"SCCNH GT 9"},{"id":"seats","label":"Seats securely fastened","gear":"seat","accepts":"FIA 8855-1999 or 8862-2009 (or racing seat accepted by Chief Scrutineer); no hinged-back or OEM seats; firmly mounted per manufacturer","rule":"SCCNH GT 9.3"},{"id":"battery","label":"Battery, battery box, + post cov''d","accepts":"Battery secure, boxed if relocated, positive post covered"},{"id":"fuel_tank","label":"Fuel tank or fuel cell","checkedBy":"team","accepts":"Tank or cell secure, no leaks"},{"id":"fuel_lines_pump","label":"Fuel lines, pump","checkedBy":"team","accepts":"Lines and pump secure, no leaks"},{"id":"fuel_cell_bulkhead","label":"Fuel cell bulkhead","checkedBy":"team","accepts":"Fuel tank/cell sealed from the cockpit"},{"id":"fire_extinguisher","label":"Fire Extinguisher: 10B:C min","gear":"fire_extinguisher","accepts":"1 x 10 B:C min. (or 2 x 5 B:C) inside the cockpit, one within reach of a seated crew member; metal strap and metal bracket; fill gauge visible","rule":"SCCNH GT 9.8","fields":[{"id":"bc_rating","label":"BC rating(s)","type":"text"}]},{"id":"triangles","label":"3 DOT triangles, 1 w/in reach","gear":"emergency_triangle","accepts":"3 emergency triangles, one within reach of a seated crew member","rule":"SCCNH GT 9.5"},{"id":"first_aid_kit","label":"First Aid kit","gear":"first_aid_kit","accepts":"Not required by the rules (N/R); if carried, secure","allowNA":true},{"id":"tow_strap","label":"Tow rope/strap","gear":"tow_rope","accepts":"Appropriate tow strap in the car","rule":"SCCNH GT 9.6"},{"id":"spill_kit","label":"Environmental spill kit","gear":"spill_kit","accepts":"Not required by the rules (N/R); if carried, secure","allowNA":true}]},{"id":"exhaust","title":"Exhaust / Sound / Restrictor","items":[{"id":"exhaust_secure","label":"Exhaust secure","checkedBy":"team","accepts":"Exhaust securely mounted, no leaks"},{"id":"sound","label":"105 dbA max @ 18\" and 45 deg","accepts":"105 dBA max at 18 in from the tail pipe, 45 degrees, 2500 rpm (including anti-lag pops)","rule":"SCCNH GT 13.3","fields":[{"id":"level","label":"Sound level","type":"number","unit":"dBA"}]},{"id":"restrictor","label":"Restrictor 30 / 32 / 34 / 36 mm","accepts":"4WD forced induction: inlet max. 36 mm, min. 3 mm wide, within 50 mm of the compressor wheel, all air through the restrictor","rule":"SCCNH GT 7A","allowNA":true,"options":["30 mm","32 mm","34 mm","36 mm"],"fields":[{"id":"size","label":"Restrictor size","type":"number","unit":"mm"}]}]},{"id":"suspension","title":"Suspension and Running Gear","items":[{"id":"tires_wheels","label":"Tires and wheels, incl spare","accepts":"Appropriate tires; DOT studded tires only at winter events; no homemade studs, bolts or chains","rule":"SCCNH GT 13.2"},{"id":"brakes","label":"Brakes","checkedBy":"team","accepts":"Firm pedal, no leaks"},{"id":"parking_brake","label":"Parking brake","checkedBy":"team","accepts":"Holds the car"},{"id":"wheel_bearings_steering","label":"Wheel bearings, steering linkage","checkedBy":"team","accepts":"No excessive play"},{"id":"shocks_suspension","label":"Shocks/suspension","checkedBy":"team","accepts":"Secure, no leaks or damage"},{"id":"brake_hoses_cables","label":"Brake hoses/cables","checkedBy":"team","accepts":"No leaks, chafing or damage"},{"id":"suspension_arms","label":"Suspension arms/mounting points","checkedBy":"team","accepts":"No cracks or damage"}]}],"signoff":[{"id":"scrutineer","label":"Scrutineer","license":false},{"id":"chief","label":"Chief Scrutineer","license":false}]}'::jsonb)
